mapper.select:
	SELECT COUNT(*)
    FROM TB_DRIVE D
    WHERE D.FRST_RGTR_ID = #{empId}
      AND D.DRIVE_SCOPE_CD = '01'
      AND D.DEL_YN = 'N'
      AND (
            (#{prntDriveItemId} IS NULL AND D.PRNT_DRIVE_ITEM_ID IS NULL)
            OR D.PRNT_DRIVE_ITEM_ID = #{prntDriveItemId}
      )

mapper.update:
	UPDATE TB_DRIVE
	SET ITEM_NM = #{itemNm},
	    LAST_MDFCN_DT = SYSDATE,
	    LAST_MDFR_ID = #{lastMdfrId}
    WHERE DRIVE_ITEM_ID = #{driveItemId}
      AND DEL_YN = 'N'

UPDATE TB_DRIVE
SET BOOKMARK_YN = #{newBookmarkYn},
	LAST_MDFCN_DT = SYSDATE,
	LAST_MDFR_ID = #{lastMdfrId}
WHERE DRIVE_ITEM_ID = #{driveItemId}
  AND DEL_YN = 'N'
